window.PORTFOLIO_PAGE_TRANSLATIONS = [["Recommendation letter guide \u2014 AX/PI Group Leader, ENG Division, Energy Solutions Business","\ucd94\ucc9c\uc11c \uc791\uc131 \uc548\ub0b4 \u2014 ES\uc0ac\uc5c5\ubd80 ENG\ubcf8\ubd80 AX/PI\uadf8\ub8f9 \uadf8\ub8f9\uc7a5"],["Recommendation letter guide","\ucd94\ucc9c\uc11c \uc791\uc131 \uc548\ub0b4"],["AX/PI Group Leader, ENG Division, Energy Solutions Business","ES\uc0ac\uc5c5\ubd80 ENG\ubcf8\ubd80 AX/PI\uadf8\ub8f9 \uadf8\ub8f9\uc7a5"],["What to select on the submission form","\uc81c\ucd9c \ud654\uba74\uc5d0\uc11c \ubb34\uc5c7\uc744 \uace0\ub974\uace0"],["and what to write in each field","\ubb34\uc5c7\uc744 \uc4f0\uba74 \ub418\ub294\uc9c0 \uc815\ub9ac\ud588\uc2b5\ub2c8\ub2e4"],["The left column shows the actual fields on UT\u2019s submission form. Blue marks the suggested choices; the right column explains the reasoning. These are suggestions only. Please change anything that does not match what you have observed.","\uc67c\ucabd\uc740 UT \uc81c\ucd9c \ud654\uba74\uc5d0 \uc2e4\uc81c\ub85c \ub098\uc624\ub294 \ud56d\ubaa9\uc785\ub2c8\ub2e4. \ud30c\ub797\uac8c \ud45c\uc2dc\ub41c \uac83\uc774 \uc81c\uc548 \ub4dc\ub9ac\ub294 \uc120\ud0dd\uc774\uace0, \uc624\ub978\ucabd\uc740 \uadf8\ub807\uac8c \uc81c\uc548 \ub4dc\ub9b0 \uc774\uc720\uc785\ub2c8\ub2e4. \uc5b4\ub514\uae4c\uc9c0\ub098 \uc81c\uc548\uc774\ub2c8 \uc2e4\uc81c\ub85c \ubcf4\uc2e0 \uac83\uacfc \ub2e4\ub974\uba74 \ubc14\uafd4 \uc8fc\uc2ed\uc2dc\uc624."],["Blue items","\ud30c\ub780 \ud56d\ubaa9"],["Suggested choices","\uc81c\uc548 \ub4dc\ub9ac\ub294 \uc120\ud0dd"],["Orange borders","\uc8fc\ud669 \ud14c\ub450\ub9ac"],["Fields with draft text","\ucd08\uc548\uc774 \ucc44\uc6cc\uc9c4 \uc785\ub825\ub780"],["Estimated time","\uc18c\uc694 \uc2dc\uac04"],["About 15 minutes","15\ubd84 \ub0b4\uc678"],["UT submission form \u00b7 original text","UT \uc81c\ucd9c \ud654\uba74 \u00b7 \uc6d0\ubb38"],["Enter your details","\uc9c1\uc811 \uc785\ub825"],["Name: [Your name in English]\\nTitle: Group Leader, AX/PI Group, ENG Division\\nOrganization: Samsung C&T Corporation","Name: [\uc131\ud568 \uc601\ubb38]\\nTitle: Group Leader, AX/PI Group, ENG Division\\nOrganization: Samsung C&T Corporation"],["Explanation","\ud55c\uad6d\uc5b4 \ud574\uc124"],["Recommender information","\ucd94\ucc9c\uc778 \uc815\ubcf4"],["\u2014 Enter your name, title, and organization.","\u2014 \uc131\ud568\u00b7\uc9c1\ud568\u00b7\uc18c\uc18d\uc744 \uc801\ub294 \uce78\uc785\ub2c8\ub2e4."],["Choose a title that makes your relationship to the applicant clear. Reviewers use this line to understand the basis of your assessment; a department name alone does not establish that relationship.","\uc9c1\ud568\uc740 \uad00\uacc4\uac00 \ub4dc\ub7ec\ub098\uac8c \uc4f0\ub294 \ud3b8\uc774 \ub0ab\uc2b5\ub2c8\ub2e4. \uc2ec\uc0ac\uc790\ub294 \uc774 \ud55c \uc904\ub85c \uc774 \uc0ac\ub78c\uc774 \ubb34\uc5c7\uc744 \uadfc\uac70\ub85c \ud3c9\uac00\ud558\ub294\uc9c0 \ud310\ub2e8\ud569\ub2c8\ub2e4. \ubd80\uc11c\uba85\ub9cc \uc801\uc73c\uba74 \uadf8 \ud310\ub2e8\uc774 \uc548 \ub429\ub2c8\ub2e4."],["Use the organization\u2019s official English name. Submission from your company email verifies your affiliation.","\uc18c\uc18d\uc740 \uc601\ubb38 \ubc95\uc778\uba85\uc73c\ub85c \uc801\uc2b5\ub2c8\ub2e4. \ud68c\uc0ac \uc774\uba54\uc77c\ub85c \uc81c\ucd9c\ub418\ubbc0\ub85c \uc18c\uc18d\uc774 \uc790\ub3d9\uc73c\ub85c \uac80\uc99d\ub429\ub2c8\ub2e4."],["Suggested selection","\uc774\uac83\uc744 \uc120\ud0dd"],["Comparative ratings in seven areas.","7\uac1c \ud56d\ubaa9 \uc0c1\ub300\ud3c9\uac00."],["Rate the applicant relative to other graduate school candidates you have known.","\uc54c\uace0 \uacc4\uc2e0 \ub2e4\ub978 \ub300\ud559\uc6d0 \uc9c0\uc6d0\uc790\uc640 \ube44\uad50\ud574 \ub4f1\uae09\uc744 \ub9e4\uae30\ub294 \uce78\uc785\ub2c8\ub2e4."],["Avoid giving the highest rating in every area","\uc804\ubd80 \ucd5c\uc0c1\uc704\ub294 \ud53c\ud558\ub294 \ud3b8\uc774 \ub0ab\uc2b5\ub2c8\ub2e4"],["If every rating is Top 5%, reviewers may see the letter as offering little differentiation. Varying the ratings makes them read as judgments based on observation. The choices below are suggestions; please adjust them to reflect your experience.","\ubaa8\ub4e0 \ud56d\ubaa9\uc774 Top 5%\uba74 \uc2ec\uc0ac\uc790\ub294 \uc774 \ucd94\ucc9c\uc11c\ub97c \ubcc0\ubcc4\ub825 \uc5c6\ub294 \uac83\uc73c\ub85c \ubd84\ub958\ud569\ub2c8\ub2e4. \ud56d\ubaa9\ubcc4\ub85c \ucc28\uc774\ub97c \ub450\uba74 \uac01 \ub4f1\uae09\uc774 \uc2e4\uc81c \uad00\ucc30\uc5d0\uc11c \ub098\uc628 \uac83\uc73c\ub85c \uc77d\ud799\ub2c8\ub2e4. \uc544\ub798\ub294 \uc81c\uc548\uc77c \ubfd0\uc774\ub2c8 \uc2e4\uc81c\ub85c \ubcf4\uc2e0 \uac83\uacfc \ub2e4\ub974\uba74 \ubc14\uafd4 \uc8fc\uc2ed\uc2dc\uc624."],["\u2014 This is the strongest point to emphasize in the application. The central argument is that someone without a computing degree taught himself to design agent systems; a low rating here would weaken that argument.","\u2014 \uc9c0\uc6d0\uc11c\uc5d0\uc11c \uac00\uc7a5 \ubc00\uc5b4\uc57c \ud558\ub294 \ud56d\ubaa9\uc785\ub2c8\ub2e4. \ube44\uc804\uacf5\uc790\uac00 \ub3c5\ud559\uc73c\ub85c \uc5d0\uc774\uc804\ud2b8 \uc2dc\uc2a4\ud15c\uc744 \uc124\uacc4\ud588\ub2e4\ub294 \uac8c \uc774 \uc9c0\uc6d0\uc758 \ud575\uc2ec \ub17c\uc9c0\ub77c, \uc5ec\uae30\uac00 \ub0ae\uc73c\uba74 \ub098\uba38\uc9c0\uac00 \ud754\ub4e4\ub9bd\ub2c8\ub2e4."],["\u2014 He writes English technical documents and public case studies himself. However, his English is not at a native-speaker level, so the very highest rating could seem overstated. One level lower is more credible.","\u2014 \uc601\ubb38 \uae30\uc220\ubb38\uc11c\uc640 \uacf5\uac1c \uc0ac\ub840\uc5f0\uad6c\ub97c \uc9c1\uc811 \uc501\ub2c8\ub2e4. \ub2e4\ub9cc \uc6d0\uc5b4\ubbfc \uc218\uc900\uc740 \uc544\ub2c8\ub77c \ucd5c\uc0c1\uc704\ub85c \uc62c\ub9ac\uba74 \uacfc\uc7a5\uc73c\ub85c \uc77d\ud799\ub2c8\ub2e4. \ud55c \ub2e8\uacc4 \uc544\ub798\uac00 \uc624\ud788\ub824 \uc2e0\ub8b0\uac00 \uac11\ub2c8\ub2e4."],["\u2014 There is no need to give a high rating if you have rarely seen him present. His experience presenting in English is also limited, so this rating is closer to the evidence.","\u2014 \ubc1c\ud45c \uc790\ub9ac\ub97c \uc790\uc8fc \ubcf4\uc2e0 \uac8c \uc544\ub2c8\ub77c\uba74 \ubb34\ub9ac\ud574\uc11c \uc62c\ub9b4 \uc774\uc720\uac00 \uc5c6\uc2b5\ub2c8\ub2e4. \uc601\uc5b4 \ubc1c\ud45c \uacbd\ud5d8\ub3c4 \uc81c\ud55c\uc801\uc774\ub77c \uc774 \uc815\ub3c4\uac00 \uc0ac\uc2e4\uc5d0 \uac00\uae5d\uc2b5\ub2c8\ub2e4."],["\u2014 His undergraduate background is mechanical and electronic control engineering, and he has been out of university for 12 years. The highest rating could prompt questions when compared with his transcript. Describe his completed company training and current GTx and MIT courses to provide context.","\u2014 \ud559\ubd80\uac00 \uae30\uacc4\u00b7\uc804\uc790\uc81c\uc5b4\uc774\uace0 \ud559\uad50\ub97c \ub5a0\ub09c \uc9c0 12\ub144\uc785\ub2c8\ub2e4. \ucd5c\uc0c1\uc704\ub97c \uc8fc\uba74 \uc2ec\uc0ac\uc790\uac00 \uc131\uc801\ud45c\uc640 \ub300\uc870\ud558\uba74\uc11c \uc758\uc2ec\ud558\uac8c \ub429\ub2c8\ub2e4. \ub300\uc2e0 \uc0ac\ub0b4 \uad50\uc721 \uc774\uc218 \uc774\ub825\uacfc \uc9c0\uae08 \ub4e3\uace0 \uc788\ub294 GTx\u00b7MIT \uacfc\uc815\uc744 \uc11c\uc220\uc5d0\uc11c \ubcf4\uc644\ud569\ub2c8\ub2e4."],["\u2014 After 12 years in industry, he built a 4,200-line calculation engine and added 223 tests outside working hours. This is the best-supported category, making the highest rating a natural choice.","\u2014 12\ub144 \ucc28 \uc9c1\uc7a5\uc778\uc774 \ud1f4\uadfc \ud6c4\uc5d0 4,200\uc904\uc9dc\ub9ac \uacc4\uc0b0 \uc5d4\uc9c4\uc744 \ub9cc\ub4e4\uace0 \ud14c\uc2a4\ud2b8 223\uac1c\ub97c \ubd99\uc600\uc2b5\ub2c8\ub2e4. \uadfc\uac70\uac00 \uac00\uc7a5 \ud655\uc2e4\ud55c \ud56d\ubaa9\uc774\ub77c \ucd5c\uc0c1\uc704\uac00 \uc790\uc5f0\uc2a4\ub7fd\uc2b5\ub2c8\ub2e4."],["\u2014 His 12 years in multinational EPC work provide the evidence. However, this category offers limited differentiation, so the highest rating adds relatively little.","\u2014 \ub2e4\uad6d\uc801 EPC \ud604\uc7a5\uc5d0\uc11c 12\ub144\uc744 \ubc84\ud2f4 \uacbd\ub825 \uc790\uccb4\uac00 \uadfc\uac70\uc785\ub2c8\ub2e4. \ub2e4\ub9cc \uc774 \ud56d\ubaa9\uc740 \ubcc0\ubcc4\ub825\uc774 \uc57d\ud574\uc11c \ucd5c\uc0c1\uc704\ub97c \uc918\ub3c4 \uc5bb\ub294 \uac8c \uc801\uc2b5\ub2c8\ub2e4."],["\u2014 The AX/PI Group manages resources and adoption, so you may not have observed him teaching. N/A is appropriate if you have not directly seen him teach. Rating an area you did not observe can also weaken the credibility of the other ratings.","\u2014 AX/PI\uadf8\ub8f9\uc740 \uc790\uc6d0\uacfc \ub3c4\uc785\uc744 \uad00\ub9ac\ud558\ub294 \uc870\uc9c1\uc774\ub77c \uad50\uc721 \uc7a5\uba74\uc744 \ubcfc \uc77c\uc774 \uc5c6\uc2b5\ub2c8\ub2e4. N/A\ub85c \ub450\uc2dc\ub294 \uac8c \ub9de\uc2b5\ub2c8\ub2e4. \uac00\ub974\uce58\ub294 \uc7a5\uba74\uc744 \uc9c1\uc811 \ubcf4\uc9c0 \uc54a\uc73c\uc168\ub2e4\uba74 N/A\uac00 \ub9de\uc2b5\ub2c8\ub2e4. \uad00\ucc30\ud558\uc9c0 \uc54a\uc740 \ud56d\ubaa9\uc5d0 \ub4f1\uae09\uc744 \ub9e4\uae30\uba74 \ub098\uba38\uc9c0 \ub4f1\uae09\uc758 \uc2e0\ub8b0\ub3c4\uae4c\uc9c0 \uac19\uc774 \ub5a8\uc5b4\uc9d1\ub2c8\ub2e4."],["How long you have known the applicant","\uc54c\uace0 \uc9c0\ub0b8 \uae30\uac04"],["You first met through the FabriX Tools competition about a year ago. Please adjust the period to your actual contact. The division\u2019s first-place result in that competition is the one outcome you directly verified, so it also comes first in the letter.","FabriX Tools \uacbd\uc9c4\ub300\ud68c\uc5d0\uc11c \ucc98\uc74c \ubd4c \ub4a4\ub85c 1\ub144 \uc815\ub3c4\uc785\ub2c8\ub2e4. \uc2e4\uc81c \uc811\uc810 \uc2dc\uc810\uc5d0 \ub9de\uac8c \uace0\uce58\uc2dc\uba74 \ub429\ub2c8\ub2e4. \uacbd\uc9c4\ub300\ud68c \ubcf8\ubd80 \ub0b4 1\uc704\ub294 \uadf8\ub8f9\uc7a5\ub2d8\uc774 \uacb0\uacfc\ub97c \uc9c1\uc811 \ud655\uc778\ud558\uc2e0 \uc720\uc77c\ud55c \uc0ac\uc548\uc774\ub77c, \ucd94\ucc9c\uc11c \ubcf8\ubb38\uc5d0\uc11c\ub3c4 \uac00\uc7a5 \uc55e\uc5d0 \ub461\ub2c8\ub2e4."],["A short period is not a problem if your later answers make clear what you observed during that time.","\uae30\uac04\uc774 \uc9e7\uc544\ub3c4 \ubb38\uc81c\ub418\uc9c0 \uc54a\uc2b5\ub2c8\ub2e4. \uc9e7\uc740 \uae30\uac04\uc5d0 \ubb34\uc5c7\uc744 \ubcf4\uc558\ub294\uc9c0\uac00 \ub4a4 \ubb38\ud56d\uc5d0\uc11c \ub4dc\ub7ec\ub098\uba74 \ub429\ub2c8\ub2e4."],["The applicant\u2019s role at the time","\ub2f9\uc2dc \uc9c0\uc6d0\uc790\uc758 \uc2e0\ubd84"],["None of the listed categories fits exactly. He was neither your student nor your direct report, so selecting \u201cother\u201d and describing the relationship is more accurate. Make your role in allocating resources clear to support the account that follows.","\ubcf4\uae30\uc5d0 \ub531 \ub9de\ub294 \ud56d\ubaa9\uc774 \uc5c6\uc2b5\ub2c8\ub2e4. \ud559\uc0dd\ub3c4 \uc544\ub2c8\uace0 \uc9c1\uc18d \ubd80\ud558\ub3c4 \uc544\ub2c8\ub2c8 other\ub97c \uace0\ub974\uace0 \uad00\uacc4\ub97c \uc9c1\uc811 \uc801\ub294 \ud3b8\uc774 \uc815\ud655\ud569\ub2c8\ub2e4. \uc790\uc6d0\uc744 \ubc30\ubd84\ud558\ub294 \uc704\uce58\ub77c\ub294 \uc810\uc774 \ub4dc\ub7ec\ub098\uc57c \ub4a4\uc758 \uc11c\uc220\uc774 \ud798\uc744 \ubc1b\uc2b5\ub2c8\ub2e4."],["Overall recommendation","\uc885\ud569 \ucd94\ucc9c \ub4f1\uae09"],["Top 2% would be inconsistent with the individual ratings above. If several areas are rated Superior while the overall assessment is at the very top, the supporting evidence may appear inconsistent.","Top 2%\ub97c \uace0\ub974\uba74 \uc55e\uc758 \ud56d\ubaa9\ubcc4 \ub4f1\uae09\uacfc \uc5b4\uae0b\ub0a9\ub2c8\ub2e4. \uac1c\ubcc4 \ud56d\ubaa9\uc5d0 Superior\uac00 \uc11e\uc5ec \uc788\ub294\ub370 \uc885\ud569\ub9cc \ucd5c\uc0c1\uc704\uba74 \uadfc\uac70\uac00 \ub9de\uc9c0 \uc54a\ub294\ub2e4\uace0 \uc77d\ud799\ub2c8\ub2e4."],["Top 10% is a strong recommendation. You may choose a higher rating if that is your assessment, but align the individual ratings with it so the evaluation is internally consistent.","Top 10%\ub294 \ucda9\ubd84\ud788 \uac15\ud55c \ub4f1\uae09\uc785\ub2c8\ub2e4. \uc2e4\uc81c\ub85c \ucd5c\uc0c1\uc704\ub77c\uace0 \ud310\ub2e8\ud558\uc2e0\ub2e4\uba74 \uc62c\ub9ac\uc154\ub3c4 \ub418\uc9c0\ub9cc, \uadf8\ub54c\ub294 \ud56d\ubaa9\ubcc4 \ub4f1\uae09\ub3c4 \uac19\uc774 \uc62c\ub824\uc57c \uc55e\ub4a4\uac00 \ub9de\uc2b5\ub2c8\ub2e4."],["Leave the","\ubc14\ub85c \uc544\ub798"],["field immediately below blank. It is optional, and an entry could raise concerns that otherwise would not arise.","\uce78\uc740 \ube44\uc6cc \ub450\uc2ed\uc2dc\uc624. \uc120\ud0dd \ud56d\ubaa9\uc774\uace0, \uc801\uc73c\uba74 \uc5c6\ub358 \uc758\ubb38\uc744 \ub9cc\ub4ed\ub2c8\ub2e4."],["How to submit the letter","\ud3b8\uc9c0 \uc81c\ucd9c \ubc29\uc2dd"],["\u2014 Choose between uploading a file and entering the text directly.","\u2014 \ud30c\uc77c \uc5c5\ub85c\ub4dc\uc640 \uc9c1\uc811 \uc785\ub825 \uc911 \uc120\ud0dd\ud569\ub2c8\ub2e4."],["Uploading is recommended","\uc5c5\ub85c\ub4dc\ub97c \uad8c\ud569\ub2c8\ub2e4"],["Review and revise the draft sent to you separately by email, then convert it to PDF and upload it. Keeping the signature block and formatting makes it read as a formal letter.","\ub530\ub85c \uba54\uc77c\ub85c \ubcf4\ub0b4\ub4dc\ub9b0 \ucd08\uc548\uc744 \ud655\uc778\u00b7\uc218\uc815\ud558\uc2e0 \ub4a4 PDF\ub85c \ubc14\uafd4 \uc62c\ub9ac\uc2dc\uba74 \ub429\ub2c8\ub2e4. \uc11c\uba85\ub780\uacfc \uc11c\uc2dd\uc774 \ub0a8\uc544 \uc788\uc5b4 \uc9c1\uc811 \uc785\ub825\ubcf4\ub2e4 \uc815\uc2dd \ubb38\uc11c\ub85c \uc77d\ud799\ub2c8\ub2e4."],["Before submitting,","\ucd08\uc548 \ub9e8 \ub05d\uc5d0 \ubd99\uc5b4 \uc788\ub294 \ud55c\uae00 \ud574\uc124 \ud398\uc774\uc9c0\ub294"],["please remove","\ubc18\ub4dc\uc2dc \uc0ad\uc81c\ud558\uace0"],["the Korean explanatory page attached at the end of the draft.","\uc81c\ucd9c\ud574 \uc8fc\uc2ed\uc2dc\uc624."],["Entering text directly is also fine. If you choose that option, copy and paste only the body of the DOCX letter.","\uc9c1\uc811 \uc785\ub825\uc744 \uace0\ub974\uc154\ub3c4 \ubb34\ubc29\ud569\ub2c8\ub2e4. \uadf8\ub54c\ub294 docx \ubcf8\ubb38\ub9cc \ubcf5\uc0ac\ud574 \ubd99\uc5ec\ub123\uc73c\uc2dc\uba74 \ub429\ub2c8\ub2e4."],["The Submit button at the bottom of the page","\ud398\uc774\uc9c0 \ub9e8 \uc544\ub798 Submit \ubc84\ud2bc"],["You cannot make changes after submission.\\nYou can use Save as often as needed before submitting.","\uc81c\ucd9c \ud6c4\uc5d0\ub294 \uc218\uc815\ud560 \uc218 \uc5c6\uc2b5\ub2c8\ub2e4.\\n\uc911\uac04 \uc800\uc7a5(Save)\uc740 \uc5ec\ub7ec \ubc88 \uac00\ub2a5\ud569\ub2c8\ub2e4."],["Submission","\uc81c\ucd9c"],["You do not need to finish in one sitting. Save your progress and return later.","\ud55c \ubc88\uc5d0 \ub05d\ub0b4\uc9c0 \uc54a\uc73c\uc154\ub3c4 \ub429\ub2c8\ub2e4. \uc911\uac04\uc5d0 \uc800\uc7a5\ud574 \ub450\uace0 \ub098\uc911\uc5d0 \uc774\uc5b4\uc11c \ud558\uc2e4 \uc218 \uc788\uc2b5\ub2c8\ub2e4."],["After submission, the applicant sees only whether the recommendation was submitted. Because the applicant has waived FERPA access, the applicant cannot view what you wrote.","\uc81c\ucd9c\uc774 \uc644\ub8cc\ub418\uba74 \uc9c0\uc6d0\uc790 \ud654\uba74\uc5d0\ub294 \uc81c\ucd9c \uc5ec\ubd80\ub9cc \ud45c\uc2dc\ub429\ub2c8\ub2e4. \uc791\uc131\ud558\uc2e0 \ub0b4\uc6a9\uc740 FERPA \ud3ec\uae30 \ucc98\ub9ac\uac00 \ub418\uc5b4 \uc788\uc5b4 \uc9c0\uc6d0\uc790\uac00 \ubcfc \uc218 \uc5c6\uc2b5\ub2c8\ub2e4."],["To complete the form.","\uc815\ub9ac."],["Select the seven ratings and overall recommendation, enter your relationship and how long you have known the applicant, then upload the letter. The suggested ratings have supporting reasons for each category. If your observations differ, your assessment takes precedence.","\ub4f1\uae09 7\uac1c\uc640 \uc885\ud569 \ub4f1\uae09\uc744 \uace0\ub974\uc2dc\uace0, \uad00\uacc4\uc640 \uae30\uac04\uc744 \uc801\uc73c\uc2e0 \ub4a4, \ud3b8\uc9c0 \ud30c\uc77c\uc744 \uc62c\ub9ac\uc2dc\uba74 \ub05d\ub0a9\ub2c8\ub2e4.\n\uc81c\uc548 \ub4dc\ub9b0 \ub4f1\uae09\uc740 \uc9c0\uc6d0\uc790\uac00 \uc784\uc758\ub85c \uc815\ud55c \uac83\uc774 \uc544\ub2c8\ub77c \ud56d\ubaa9\ubcc4 \uadfc\uac70\ub97c \ubd99\uc5ec \ub454 \uac83\uc785\ub2c8\ub2e4. \ub2e4\ub974\uac8c \ubcf4\uc168\ub2e4\uba74 \uadf8\ucabd\uc774 \ub9de\uc2b5\ub2c8\ub2e4."],["Questions.","\ubb38\uc758."],["Please contact me if you encounter any difficulty. Questions about the university\u2019s system can also be sent to gradref@austin.utexas.edu.","\uc9c4\ud589 \uc911 \ub9c9\ud788\uc2dc\ub294 \ubd80\ubd84\uc774 \uc788\uc73c\uba74 \uc5b8\uc81c\ub4e0 \uc5f0\ub77d \uc8fc\uc2ed\uc2dc\uc624. \ud559\uad50 \uc2dc\uc2a4\ud15c \uc790\uccb4\uc5d0 \ub300\ud55c \ubb38\uc758\ub294 gradref@austin.utexas.edu \ub85c\ub3c4 \uac00\ub2a5\ud569\ub2c8\ub2e4."]];
